@startuml

enum BicycleType {
  ROAD
  MOUNTAIN
  BMX
  HYBRID
}

class Client {
  + NIN : string
  + TIN : string
  + Name : string
  + Address : string
}

class BicycleModel {
  + Name : string
  + Type : BicycleType
  + Gears : int
}

class Bicycle {
  + ID : string
}

class Store {
  + Name : string
  + Address : string
}

class Reservation {
  + PickupDate : date
}

class Rental {
  + ReturnDate : date
}

Client "1" -- "*" Reservation : makes
BicycleModel "1" -- "*" Reservation : requested in
Store "1" -- "*" Reservation : pickup location
Reservation "1" -- "0..1" Rental : becomes
Bicycle "1" -- "0..1" Rental : is rented in
Bicycle "*" -- "1" BicycleModel : is a model of
Bicycle "1" -- "1" Store : stored at

@enduml

